// OPTION_A_V3_PROJECTED_WALL: experimental P1+BF3 projected wall-layer operator.
// For a wall-owner tet, replace the two tangential shear modes generated by
// the vertex opposite the wall face. Exact frozen-coefficient identity:
//   K_new = K_deviatoric - C C^T / alpha + beta * Bp^T Pt Bp
// C_{a,i,t} = integral nu_eff * (n.grad(phi_opp)) * g_{a,i,t} dV
// alpha     = integral nu_eff * (n.grad(phi_opp))^2 dV
// g_{a,i}   = Pt [(grad(phi_a) e_i + e_i grad(phi_a)) n].
// The C vectors are tangent to the physical wall, making the removed term
// the K_s-orthogonal 2-mode projection. No wall-normal penalty or Robin term.
// This is *not* a proof of continuum wall-function consistency.
// C and alpha use the same Keast-24 quadrature and local_SST provider as V2.
// Beta uses the SAME frozen F2 face-fitted Spalding utau and the existing
// 12-point first-tet column-average bp cache, not the physical wall trace.

__device__ __forceinline__ double option_a_v3_pij(
    const double n[3],int i,int j){
  return (i==j?1.0:0.0)-n[i]*n[j];
}
__device__ __forceinline__ double option_a_v3_cdot(
    const double*C,int a,int i,int b,int j){
  const double*ca=C+9*a+3*i,*cb=C+9*b+3*j;
  return ca[0]*cb[0]+ca[1]*cb[1]+ca[2]*cb[2];
}

// Once per physical wall face and SIMPLE step, NEVER per Krylov matvec.
__global__ void option_a_v3_build(
    const hxt5b::TetFacePlan* faces,int nf,
    const hxt5b::TetWallQuadCache* quads,
    const nodals_hxt1::Point* pts,const nodals_hxt1::TetConn* tc,
    const nodals_hxt1::TetVel* tv,const nodals_hxt1::TetGeom* tg,
    const Real*ux,const Real*uy,const Real*uz,const Real*k,const Real*omega,
    const double*faceFit,double radius,double nu,double kFloor,double omegaFloor,
    double*faceBeta,double*faceAlpha,double*faceC,
    double*stats,unsigned long long*bad)
{
  const int fi=(int)blockIdx.x;if(fi>=nf)return;
  const auto f=faces[fi];const int cell=f.cell,tid=(int)threadIdx.x;
  const double n[3]={f.n[0],f.n[1],f.n[2]};
  __shared__ Real U[3][8],K[8],W[8];
  __shared__ Real GP[24][8][3];
  __shared__ double QNU[24];
  if(tid<8){
    const int gid=tv[cell].g[tid];
    U[0][tid]=ux[gid];U[1][tid]=uy[gid];U[2][tid]=uz[gid];
    K[tid]=k[gid];W[tid]=omega[gid];
  }
  __syncthreads();
  if(tid<24){
    const double l[4]={hxt5a::h5_tet24_l0[tid],hxt5a::h5_tet24_l1[tid],
       hxt5a::h5_tet24_l2[tid],hxt5a::h5_tet24_l3[tid]};
    double ph[8],gr[8][3],gp[8][3];
    hxt2::tet_basis(l[0],l[1],l[2],l[3],ph,gr);
    hxt2::tet_phys_grad(gr,tg[cell],gp);
    Real gu[9]={},gk[3]={},gw[3]={},kv=Real(0),wv=Real(0);
    for(int a=0;a<8;++a){
      const Real pa=(Real)ph[a];kv+=K[a]*pa;wv+=W[a]*pa;
      for(int d=0;d<3;++d){
        const Real gd=(Real)gp[a][d];
        GP[tid][a][d]=gd;
        gu[d]+=U[0][a]*gd;gu[3+d]+=U[1][a]*gd;gu[6+d]+=U[2][a]*gd;
        gk[d]+=K[a]*gd;gw[d]+=W[a]*gd;
      }
    }
    double x=0.,y=0.;
    for(int a=0;a<4;++a){
      const auto p=pts[tc[cell].v[a]];
      x+=l[a]*p.x;y+=l[a]*p.y;
    }
    const auto ss=hxt5c::local_sst((Real)x,(Real)y,(Real)radius,(Real)nu,
      gu,kv,wv,gk,gw,(Real)kFloor,(Real)omegaFloor);
    QNU[tid]=(nu+(double)ss.nut)*
      (double)(tg[cell].det*hxt5a::h5_tet24_w[tid]);
  }
  __syncthreads();
  // One face average of the actual 12 cached normal-column matching velocities.
  if(tid==0){
    double area=0.,u[3]={};
    for(int q=0;q<12;++q){
      const auto ca=quads[(std::size_t)12*fi+q];
      area+=ca.w;
      for(int a=0;a<8;++a){
        const double w=ca.w*ca.bp[a];
        u[0]+=w*(double)U[0][a];
        u[1]+=w*(double)U[1][a];
        u[2]+=w*(double)U[2][a];
      }
    }
    if(area>0.)for(int j=0;j<3;++j)u[j]/=area;
    const double normal=u[0]*n[0]+u[1]*n[1]+u[2]*n[2];
    const double ut[3]={u[0]-normal*n[0],u[1]-normal*n[1],u[2]-normal*n[2]};
    const double speed=sqrt(ut[0]*ut[0]+ut[1]*ut[1]+ut[2]*ut[2]);
    const double utau=faceFit[3ull*(std::size_t)fi+1];
    const double tau=utau*utau;
    double alpha=0.;
    for(int q=0;q<24;++q){
      const double gn=(double)GP[q][f.lf][0]*n[0]+
                     (double)GP[q][f.lf][1]*n[1]+
                     (double)GP[q][f.lf][2]*n[2];
      alpha+=QNU[q]*gn*gn;
    }
    // Do not hide a singular wall conductance behind an arbitrary viscosity cap.
    if(!(faceFit[3ull*(std::size_t)fi]>0.) || !(area>0.) ||
       !(alpha>0.) || !isfinite(alpha) || !isfinite(tau) ||
       !isfinite(speed) || (tau>0. && speed<=1.e-12)){
      atomicAdd(bad,1ULL);
      if(fi<12)printf("NODALS_OPTION_A_V3_INVALID face=%d tau=%.8e speed=%.8e alpha=%.8e area=%.8e\n",
                    fi,tau,speed,alpha,area);
      faceBeta[fi]=0.;faceAlpha[fi]=0.;
    }else{
      const double beta=tau>0.?tau/speed:0.;
      if(!(beta>=0.) || !isfinite(beta)){
        atomicAdd(bad,1ULL);faceBeta[fi]=0.;faceAlpha[fi]=0.;
      }else{
        faceBeta[fi]=beta;faceAlpha[fi]=alpha;
        if(stats){
          atomicAdd(stats+0,area);
          atomicAdd(stats+1,area*tau);
          atomicAdd(stats+2,area*beta);
        }
      }
    }
  }
  // Cache C_{a,i,t}; tangent component t=0,1,2.
  for(int id=tid;id<72;id+=(int)blockDim.x){
    const int a=id/9,comp=(id/3)%3,t=id%3;
    double sum=0.;
    for(int q=0;q<24;++q){
      const auto*ga=GP[q][a];const auto*ge=GP[q][f.lf];
      const double dna=(double)ga[0]*n[0]+(double)ga[1]*n[1]+(double)ga[2]*n[2];
      const double dne=(double)ge[0]*n[0]+(double)ge[1]*n[1]+(double)ge[2]*n[2];
      const double gat=(comp==t?dna:0.)+n[comp]*(double)ga[t]-2.*n[comp]*n[t]*dna;
      sum+=QNU[q]*dne*gat;
    }
    faceC[(std::size_t)72*fi+id]=sum;
  }
}

// Exact nine-block local CSR correction before the common BF3 T/Tt transforms.
__global__ void option_a_v3_add_m3(
    const hxt5b::TetFacePlan*faces,int nf,
    const hxt5b::TetWallQuadCache*quads,
    const std::int32_t*slots,std::size_t nnz,
    const double*beta,const double*alpha,const double*C,Real*mat)
{
  const int fi=(int)blockIdx.x;if(fi>=nf)return;
  const auto f=faces[fi];const double n[3]={f.n[0],f.n[1],f.n[2]};
  const double*cc=C+(std::size_t)72*fi;
  const double b=beta[fi],inv=1./alpha[fi];
  for(int ix=(int)threadIdx.x;ix<576;ix+=(int)blockDim.x){
    const int blk=ix/64,i=blk/3,j=blk%3,a=(ix%64)/8,c=ix%8;
    double gram=0.;
    for(int q=0;q<12;++q){
      const auto ca=quads[(std::size_t)12*fi+q];
      gram+=ca.w*ca.bp[a]*ca.bp[c];
    }
    const double correction=b*option_a_v3_pij(n,i,j)*gram
         -inv*option_a_v3_cdot(cc,a,i,c,j);
    const std::int32_t pos=slots[(std::size_t)f.cell*64u+(std::size_t)(8*a+c)];
    atomicAdd(mat+((std::size_t)i*3+j)*nnz+(std::size_t)pos,(Real)correction);
  }
}

// Matrix-free action on physical P1+BF3 coefficients, before Tt and masks.
__global__ void option_a_v3_apply(
    const hxt5b::TetFacePlan*faces,int nf,
    const hxt5b::TetWallQuadCache*quads,
    const nodals_hxt1::TetVel*tv,
    const double*beta,const double*alpha,const double*C,
    int nv,const Real*x,Real*y)
{
  const int fi=(int)blockIdx.x;if(fi>=nf)return;
  const auto f=faces[fi];const int tid=(int)threadIdx.x;
  const double n[3]={f.n[0],f.n[1],f.n[2]};
  const double*cc=C+(std::size_t)72*fi;
  __shared__ double cp[3],wt[12][3];
  if(tid==0){
    cp[0]=cp[1]=cp[2]=0.;
    for(int a=0;a<8;++a)for(int i=0;i<3;++i){
      const double xx=(double)x[(std::size_t)i*nv+tv[f.cell].g[a]];
      for(int t=0;t<3;++t)cp[t]+=cc[9*a+3*i+t]*xx;
    }
  }
  if(tid<12){
    const auto ca=quads[(std::size_t)12*fi+tid];double v[3]={};
    for(int a=0;a<8;++a)for(int i=0;i<3;++i)
      v[i]+=ca.bp[a]*(double)x[(std::size_t)i*nv+tv[f.cell].g[a]];
    const double ndot=v[0]*n[0]+v[1]*n[1]+v[2]*n[2];
    for(int i=0;i<3;++i)wt[tid][i]=v[i]-ndot*n[i];
  }
  __syncthreads();
  if(tid<24){
    const int a=tid/3,i=tid%3;
    double result=0.;
    for(int q=0;q<12;++q){
      const auto ca=quads[(std::size_t)12*fi+q];
      result+=beta[fi]*ca.w*ca.bp[a]*wt[q][i];
    }
    for(int t=0;t<3;++t)result-=cc[9*a+3*i+t]*cp[t]/alpha[fi];
    atomicAdd(y+(std::size_t)i*nv+tv[f.cell].g[a],(Real)result);
  }
}
